package edu.hfut.campus.controller;import java.util.*;import org.springframework.web.bind.annotation.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import edu.hfut.campus.dao.DomainMapper;import edu.hfut.campus.entity.AuditEntity;import edu.hfut.campus.exception.ApiException;import static edu.hfut.campus.dto.Responses.map;
@RestController @ConditionalOnProperty(name="p4c.internal.enabled",havingValue="true")public class ExceptionAuditController{
 private final DomainMapper d;public ExceptionAuditController(DomainMapper d){this.d=d;}
 @PostMapping("/internal/exception-audits")public Object accept(@RequestBody Map<String,String>b){String id=b.get("eventId"),target=b.get("target"),action=b.get("action");if(id==null||!id.matches("P4C-[0-9a-f-]{36}")||target==null||target.length()>128||!Arrays.asList("异常处置","异常状态更新","新增黑名单","更新黑名单").contains(action))throw new ApiException(400,"审计事件参数不正确");AuditEntity a=new AuditEntity();a.id=id;a.time=b.get("time");a.actor=b.get("actor");a.role=b.get("role");a.action=action;a.target=target;a.result="成功";d.legacyAudit(a);return map("accepted",true,"eventId",id);}
}
